   FUNÇÃO ATÔMICA DE PRÉ-COBRANÇA (o insert..on conflict..returning trava a linha e serializa concorrentes):
   create function public.contencao_tentar(p_chave text, p_max int, p_janela interval, p_escada int[]) returns table(permitido boolean, retry_after_s int) language plpgsql as $$
   declare v auth_contencao;
   begin
     insert into auth_contencao(chave) values (p_chave) on conflict (chave) do update set atualizado_em = now() returning * into v;
     if v.bloqueado_ate is not null and v.bloqueado_ate > now() then return query select false, ceil(extract(epoch from v.bloqueado_ate - now()))::int; return; end if;
     if v.primeira_falha_em < now() - p_janela then update auth_contencao set falhas = 1, primeira_falha_em = now() where chave = p_chave; return query select true, 0; return; end if;
     update auth_contencao set falhas = falhas + 1 where chave = p_chave returning * into v;
     if v.falhas > p_max then
       update auth_contencao set nivel = nivel + 1, bloqueado_ate = now() + make_interval(secs => p_escada[least(v.nivel + 1, cardinality(p_escada))]), falhas = 0, primeira_falha_em = now() where chave = p_chave returning * into v;
       return query select false, ceil(extract(epoch from v.bloqueado_ate - now()))::int; return;
     end if;
     return query select true, 0;
   end $$;
   + contencao_zerar(p_chave) (delete da linha — sucesso limpa tudo, minimização LGPD). Grant execute só ao role do backend.

