   @router.post("/auth/login")
   @limiter.limit(settings.rate_limit_login_ip, key_func=chave_ip_confiavel)
   async def login(...):
     async def _fluxo():
       chave = chave_conta(body.email)
       ok, retry = contencao_tentar(session, chave, ...)        # PRÉ-COBRANÇA, antes do GoTrue
       if not ok: return _resp_429(retry_arredondado_minuto)    # corpo idêntico p/ conta inexistente
